// Confirma que el aviso viene del portal y arma un texto listo para mandar por correo o Slack.
const ESPERADO = 'cambiar-por-una-clave-larga';   // la misma que N8N_WEBHOOK_SECRET en el .env del portal
const item = $input.first().json;
const token = (item.headers || {})['x-portal-token'] || '';
if (ESPERADO && token !== ESPERADO) {
  throw new Error('El aviso no trae la clave compartida correcta: se descarta.');
}
const b = item.body || {};
const o = b.order || {};
let texto = b.action + (b.detail ? ' — ' + b.detail : '');
if (b.event.startsWith('pedido')) {
  const cambio = o.type === 'codigo' ? `${o.from} → ${o.to}` : `reemplazos de ${o.code}`;
  texto = `Pedido #${o.id} (${cambio}): ${b.action}. Estado: ${o.status}. Lo pidió ${o.requested_by}` +
          (o.decided_by ? `, lo aprobó ${o.decided_by}` : '') + `. ${o.url || ''}`;
}
return [{ json: { evento: b.event, texto, pedido: o, original: b } }];
